<?php require __DIR__.'/config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(400);exit('CSRF');}$q=db()->prepare('SELECT id,username,password_hash FROM usuarios WHERE username=?');$q->execute([trim($_POST['username']??'')]);$u=$q->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['username']=$u['username'];$q=db()->prepare('INSERT INTO historial_sesiones(usuario_id,ip_o_dispositivo) VALUES(?,?)');$q->execute([$u['id'],substr(($_SERVER['REMOTE_ADDR']??'').' | '.($_SERVER['HTTP_USER_AGENT']??''),0,255)]);header('Location: ../index.html?sesion=ok');exit;}$err='Credenciales incorrectas.';}formpage('Iniciar sesión');echo htmlspecialchars($err).'<form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input name="username" required placeholder="Username"><input name="password" type="password" required placeholder="Contraseña"><button>Entrar</button></form><a href="register.php">Crear cuenta</a></main>';